window.docContents[178].resolve({"/rules/PL1002/#PL1002-example":{"contents":"\n\nThe correction fills the same reflexivity proof with rfl. The checked violation records Lean's original sorry warning as well; the corrected file passes the ordinary warning-rejecting gate.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1002: Proof holes are forbidden","header":"Checked example","id":"/rules/PL1002/#PL1002-example"},"/rules/PL2001/#PL2001-example":{"contents":"\n\nThe correction removes the unavailable Lake dependency from the configuration; the requested reflexivity source is unchanged.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2001: The declared Lean environment must be available","header":"Checked example","id":"/rules/PL2001/#PL2001-example"}});